void xfs_da_fix_hash_path(struct xfs_da_state *state, struct xfs_da_state_path *path)
{
    struct xfs_da_intnode *node;
    struct xfs_dir2_leaf *leaf;
    struct xfs_dir2_leaf_entry *lep;
    struct xfs_dir2_block *block;
    xfs_dir2_data_off_t hashval;
    int i, j;

    hashval = 0;
    for (i = 0; i < path->active; i++) {
        node = path->paths[i].bp->b_addr;
        if (be32_to_cpu(node->magic) == XFS_DA_NODE_MAGIC) {
            for (j = 0; j < node->count; j++) {
                if (hashval == 0) {
                    hashval = be32_to_cpu(node->hashval[j]);
                } else {
                    node->hashval[j] = cpu_to_be32(hashval);
                }
            }
        } else if (be32_to_cpu(node->magic) == XFS_DIR2_LEAFN_MAGIC) {
            leaf = (struct xfs_dir2_leaf *)node;
            lep = leaf->entries;
            for (j = 0; j < be16_to_cpu(leaf->count); j++) {
                if (hashval == 0) {
                    hashval = be32_to_cpu(lep[j].hashval);
                } else {
                    lep[j].hashval = cpu_to_be32(hashval);
                }
            }
        } else if (be32_to_cpu(node->magic) == XFS_DIR2_BLOCK_MAGIC) {
            block = (struct xfs_dir2_block *)node;
            for (j = 0; j < be16_to_cpu(block->count); j++) {
                if (hashval == 0) {
                    hashval = be32_to_cpu(block->entries[j].hashval);
                } else {
                    block->entries[j].hashval = cpu_to_be32(hashval);
                }
            }
        }
    }
}

void fix_hash_path(struct xfs_da_state *state, struct xfs_da_state_path *path) {
    xfs_hash_t hash;
    int level;
    struct xfs_da_node_entry *bnode;
    struct xfs_dir2_leaf *leaf;
    struct xfs_dir2_leaf_entry *leafent;
    struct xfs_dir2_data_entry *dp;
    struct xfs_da_state_path *pathp;

    pathp = path;
    hash = pathp->at_tail->hashval;
    for (level = pathp->active_levels - 1; level >= 0; level--) {
        switch (be32_to_cpu(pathp->path[level].magic)) {
        case XFS_DA_NODE_MAGIC:
            bnode = (struct xfs_da_node_entry *)pathp->path[level].bp->data;
            hash = be32_to_cpu(bnode->hashval[level]);
            break;
        case XFS_DIR2_LEAFN_MAGIC:
            leaf = (struct xfs_dir2_leaf *)pathp->path[level].bp->data;
            leafent = (struct xfs_dir2_leaf_entry *)leaf->entries;
            hash = be32_to_cpu(leafent[level].hash);
            break;
        case XFS_DIR2_DATA_MAGIC:
            dp = (struct xfs_dir2_data_entry *)pathp->path[level].bp->data;
            hash = be32_to_cpu(dp[level].hash);
            break;
        }

        if (hash == pathp->at_tail->hashval)
            break;
    }
}

void fix_hash_path(struct xfs_da_state *state, struct xfs_da_state_path *path) {
    __u16 hashval;
    struct xfs_da_intnode *node;
    int i, j;

    hashval = xfs_da_get_hashval(path->leaf);
    for (i = path->active_leaves; i > 0; i--) {
        node = path->nodes[i - 1];
        for (j = 0; j < node->count; j++) {
            if (node->hashval[j] == hashval) {
                node->hashval[j] = state->hashval;
                xfs_trans_log_block(state->tp, node->bp, XFS_DA_LOG_CHANGE);
                break;
            }
            hashval = node->hashval[j];
        }
        if (j < node->count)
            break;
    }
}

void xfs_da_fix_hash_path(struct xfs_da_state *state, struct xfs_da_state_path *path)
{
    struct xfs_da_intnode *node;
    struct xfs_dir2_leaf *leaf;
    struct xfs_dir2_data_entry *bestent = NULL;
    struct xfs_dir2_leaf_entry *best;
    __u32 hashval, curhash;
    int level, i;

    hashval = 0;

    for (level = path->active - 1; level >= 0; level--) {
        node = path->path[level].bp->data;
        if (be16_to_cpu(node->magic) == XFS_DIR2_LEAFN_MAGIC) {
            leaf = (struct xfs_dir2_leaf *)node;
            curhash = be32_to_cpu(leaf->hdr.info.hashval);
            if (curhash == 0)
                hashval = 0;
            else {
                for (i = 0; i < be16_to_cpu(leaf->hdr.count); i++) {
                    if (be32_to_cpu(leaf->ents[i].hashval) == hashval) {
                        best = &leaf->ents[i];
                        bestent = (struct xfs_dir2_data_entry *)((char *)leaf +
                                be16_to_cpu(best->address));
                        break;
                    }
                }
            }
        } else {
            curhash = be32_to_cpu(node->hashval);
            if (curhash == 0)
                hashval = 0;
            else {
                for (i = 0; i < be16_to_cpu(node->count); i++) {
                    if (be32_to_cpu(node->hashes[i]) == hashval) {
                        node = (struct xfs_da_intnode *)((char *)node + node->offs[i]);
                        break;
                    }
                }
            }
        }
    }

    if (bestent)
        xfs_da_log_data_entry(state->args->trans, bestent);
}

void xfs_da_fix_hashpath(struct xfs_da_state *state, struct xfs_da_state_path *path) {
    struct xfs_da_intnode *node;
    xfs_dahash_t hash;
    int i, j;

    hash = xfs_da_get_hashval(path->path_val, path->path_size);

    for (i = 0; i < path->active; i++) {
        struct xfs_buf *bp = path->path[i].bp;
        struct xfs_dir2_leaf_hdr *hdr = XFS_BUF_TO_DIR2_LEAF_HDR(bp);

        if (be32_to_cpu(hdr->magic) == cpu_to_be32(XFS_DIR2_LEAF1_MAGIC)) {
            struct xfs_dir2_leaf1 *leaf1 = XFS_BUF_TO_DIR2_LEAF1_HDR(bp);
            hash = be32_to_cpu(leaf1->hashval);
        } else if (be32_to_cpu(hdr->magic) == cpu_to_be32(XFS_DIR2_LEAFN_MAGIC)) {
            struct xfs_dir2_leaf *leafn = XFS_BUF_TO_DIR2_LEAF_HDR(bp);
            hash = be32_to_cpu(leafn->hashval);
        }

        for (j = 0; j < path->path[i].blkno + 1; j++) {
            if (hash == 0)
                break;

            xfs_da_set_hashval(path->path[i].hashval, hash);
            xfs_trans_log_block(state->tp, bp, XFS_DA_LOGCHANGE);
            hash = xfs_da_get_hashval(path->path[i].hashval, sizeof(xfs_dahash_t));
        }
    }
}
